module.exports.config = {
    name: "antiChangeAvatar",
    eventType: ["log:thread-image"],
    version: "1.0.0",
    credits: "Kaori Waguri",
    description: "Chống đổi ảnh avatar nhóm - tự động đổi lại ảnh cũ khi có người thay đổi",
    envConfig: {
        enable: true
    }
};

module.exports.run = async function({ api, event, Threads }) {
    const fs = require("fs");
    const axios = require("axios");
    const path = require("path");

    if (!global.configModule[this.config.name].enable) return;

    const { threadID, author, logMessageData } = event;
    const botID = api.getCurrentUserID();

    // Không xử lý nếu là bot thay đổi
    if (author == botID) return;

    // Đường dẫn lưu ảnh avatar nhóm
    const avatarDir = path.join(__dirname, "cache", "groupAvatars");
    const avatarPath = path.join(avatarDir, `${threadID}.jpg`);

    // Tạo thư mục nếu chưa có
    if (!fs.existsSync(avatarDir)) {
        fs.mkdirSync(avatarDir, { recursive: true });
    }

    try {
        // Lấy thông tin nhóm hiện tại
        const threadInfo = await api.getThreadInfo(threadID);
        const threadName = threadInfo.threadName || "Nhóm";

        // Nếu chưa có ảnh backup, lưu ảnh hiện tại làm backup
        if (!fs.existsSync(avatarPath)) {
            if (logMessageData.image && logMessageData.image.url) {
                try {
                    const response = await axios.get(logMessageData.image.url, {
                        responseType: 'stream'
                    });

                    const writer = fs.createWriteStream(avatarPath);
                    response.data.pipe(writer);

                    await new Promise((resolve, reject) => {
                        writer.on('finish', resolve);
                        writer.on('error', reject);
                    });

                    console.log(`[Anti Change Avatar] Đã lưu ảnh backup cho nhóm ${threadName}`);
                    return;
                } catch (error) {
                    console.log(`[Anti Change Avatar] Lỗi khi lưu ảnh backup: ${error.message}`);
                    return;
                }
            }
            return;
        }

        // Nếu đã có ảnh backup, thực hiện đổi lại
        if (fs.existsSync(avatarPath)) {
            // Delay 2 giây để tránh spam
            await new Promise(resolve => setTimeout(resolve, 2000));

            // Đổi lại ảnh avatar nhóm
            await api.changeGroupImage(fs.createReadStream(avatarPath), threadID);

            // Lấy tên người thay đổi
            const userInfo = await api.getUserInfo(author);
            const userName = userInfo[author]?.name || "Người dùng";

            // Gửi thông báo
            const message = `🛡️ CHỐNG ĐỔI ẢNH NHÓM 🛡️\n\n` +
                          `👤 ${userName} vừa cố gắng đổi ảnh nhóm!\n` +
                          `🔄 Bot đã tự động khôi phục lại ảnh cũ\n` +
                          `⚠️ Vui lòng không thay đổi ảnh nhóm!\n\n` +
                          `📌 Credit: Kaori Waguri`;

            await api.sendMessage(message, threadID);

            console.log(`[Anti Change Avatar] Đã khôi phục ảnh nhóm ${threadName} - Người thay đổi: ${userName}`);
        }

    } catch (error) {
        console.log(`[Anti Change Avatar] Lỗi: ${error.message}`);

        // Gửi thông báo lỗi cho admin
        if (global.config.ADMINBOT && global.config.ADMINBOT[0]) {
            api.sendMessage(`[Anti Change Avatar] Lỗi tại nhóm ${threadID}: ${error.message}`, global.config.ADMINBOT[0]);
        }
    }
};

