module.exports.run = async function({ api, event, args }) {
  if(args.length !== 5) {
    return api.sendMessage(
      "❌ Sai cú pháp!\nĐúng: .td <uid> <giờ bắt đầu> <ngày bắt đầu> <giờ kết thúc> <ngày kết thúc>\nVí dụ: .td 6706892146 20h 2025-07-17 22h 2025-07-17",
      event.threadID,
      event.messageID
    );
  }

  const [uid, startTime, startDate, endTime, endDate] = args;

  // Chuyển 20h -> 20:00, ví dụ
  const formatTime = (timeStr) => timeStr.replace('h', ':00');

  const start = `${startDate}T${formatTime(startTime)}`;
  const end = `${endDate}T${formatTime(endTime)}`;

  // URL giả định (cần bạn xác nhận)
  const url = `https://congdong.ff.garena.vn/tinh-diem?uid=${uid}&start=${encodeURIComponent(start)}&end=${encodeURIComponent(end)}`;

  try {
    const response = await axios.get(url, {
      headers: {
        Cookie: COOKIE,
        'User-Agent': 'Mozilla/5.0'
      }
    });

    const $ = cheerio.load(response.data);

    // parse bảng điểm tùy theo cấu trúc thực tế
    const rows = $('table tr');
    if(rows.length < 2) return api.sendMessage("Không tìm thấy bảng điểm cho khoảng thời gian này.", event.threadID, event.messageID);

    let msg = `🏆 Bảng điểm từ ${start} đến ${end}:\n\n`;

