        const kills = $(cols[2]).text().trim();
        const matches = $(cols[3]).text().trim();
        msg += `${i}. ${name} - Win: ${wins}, Kill: ${kills}, Matches: ${matches}\n`;
      }
    });

    return api.sendMessage(msg, event.threadID, event.messageID);

